# 1) Try to find exact duplications: for each shift d, count matches between seq[i] and seq[i+d]
def best_shifts(min_len=200):
    results=[]
    for d in range(30, L-30):
        cnt = 0
        for i in range(L-d):
            if seq[i] == seq[i+d]:
                cnt += 1
        score = cnt/(L-d)
        results.append((score, d, cnt))
    results.sort(reverse=True)
