seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
L = len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# Longest inverted repeat (palindrome) allowing mismatch, via exact palindrome scan done right
best = (0, None)
for i in range(L):
    k = 0
    while i + 2*k + 2 <= L and seq[i+k] == rc(seq[i+k]) and False: k+=1
# simpler: longest even 'stem': center-symmetric palindrome
def longest_hairpin(mismatch=0):
    best_len, best_pos, best_tid = 0, None, None
    for i in range(L):
        arm = 1
        while i - arm >= 0 and i + arm < L and seq[i-arm] == rc(seq[i+arm]):
            arm += 1
        arm -= 1
        if arm*2+1 > best_len:
            best_len, best_pos = arm*2+1, i
    # even-arm (perfect palindrome, no center)
    best_e = (0, None)
    for i in range(L-1):
        arm = 0
        while i - arm >= 0 and i+1+arm < L and seq[i-arm] == rc(seq[i+1+arm]):
            arm += 1
        if arm*2 > best_e[0]:
            best_e = (arm*2, i-arm+1)
    return best_len, best_pos, best_e

bl, bp, be = longest_hairpin()
print(f"Longest palindromic inverted repeat (odd arm): {bl} nt at pos {bp}; even: {be[0]} nt at {be[1]}")

# low-complexity windows
def entropy(s):
    c = Counter(s); n=len(s)
    return -sum((v/n)*math.log2(v/n) for v in c.values() if v)
lows = [(i, round(entropy(seq[i:i+150]),2)) for i in range(0, L-150, 50) if entropy(seq[i:i+150]) < 1.75]
print("Low-entropy 150bp windows:", lows if lows else "none < 1.75")

# tandem repeats
tandem_hits=[]
i=0
for unit_len in (2,3,4,5):
    i=0
    while i + unit_len*3 <= L:
        u = seq[i:i+unit_len]
        if 'N' in u: i+=1; continue
        nrep = 1
        while i+nrep*unit_len + unit_len <= L and seq[i+nrep*unit_len: i+(nrep+1)*unit_len]==u:
            nrep+=1
        if nrep >= 4:
            tandem_hits.append((i, u, nrep))
            i += nrep*unit_len
        else:
            i+=1
print("Microsatellite tandem repeats (>=4 units):", tandem_hits if tandem_hits else "none")

# nearest duplicate segments with <=1 mismatch, len>=12 spaced >200nt apart
seen = {}
duplist=[]
for i in range(L-12):
    w = seq[i:i+12]
    seen.setdefault(w, []).append(i)
for w, pos in seen.items():
    if len(pos)>1 and max(pos)-min(pos) > 300:
        duplist.append((w, pos[0], pos[-1]))
duplist = [d for d in duplist if not any(b <= a[1] and c >= a[2] for a in duplist for b,c in [(d[1],d[2])] if a != d)]
duplist.sort(key=lambda x: x[1])
merged=[]
for w,a,b in duplist:
