        merged[-1] = (merged[-1][0], merged[-1][1], b+2 if b+2<=L else b)
    else:
        merged.append((w,a,b))
print("12-mers duplicated >300nt apart (merged):", len(merged))
for w,a,b in merged[:20]: print("  ", a, b, b-a, w)
